import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { API_URL } from '../utils/api';

const History = () => {
  const [history, setHistory] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [scrollPosition, setScrollPosition] = useState(0);
  const [currentPage, setCurrentPage] = useState(1);
  const tableContainerRef = React.useRef(null);
  const itemsPerPage = 10;

  useEffect(() => {
    fetchHistory();
    const interval = setInterval(fetchHistory, 5000);
    return () => clearInterval(interval);
  }, []);

  const fetchHistory = async () => {
    try {
      console.log('Fetching history from:', `${API_URL}/history`);
      const result = await axios.get(`${API_URL}/history`);
      console.log('History response:', result.data);
      setHistory(result.data.history || []);
      setCurrentPage(1);  // Reset to first page
      setError(null);
      setLoading(false);
    } catch (err) {
      console.error('History fetch error:', err);
      setError('Failed to load history: ' + err.message);
      setHistory([]);
      setLoading(false);
    }
  };

  const handleScroll = (direction) => {
    if (!tableContainerRef.current) return;
    const container = tableContainerRef.current;
    const scrollAmount = 300;
    const newPosition = direction === 'left' 
      ? Math.max(0, scrollPosition - scrollAmount)
      : scrollPosition + scrollAmount;
    
    container.scrollLeft = newPosition;
    setScrollPosition(newPosition);
  };

  if (loading) {
    return <div className="component-container"><p>Loading history...</p></div>;
  }

  return (
    <div className="component-container">
      <h2>Processing History</h2>
      
      <div style={{ textAlign: 'center', marginBottom: '20px' }}>
        <button onClick={fetchHistory} className="button">
          Refresh
        </button>
      </div>

      {error && <div className="error">{error}</div>}

      {history.length === 0 ? (
        <p style={{ textAlign: 'center', color: '#666' }}>No processing history yet.</p>
      ) : (
        <div>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '15px' }}>
            <button 
              onClick={() => handleScroll('left')}
              style={{
                padding: '8px 12px',
                backgroundColor: '#5d35c4',
                color: '#fff',
                border: 'none',
                borderRadius: '4px',
                cursor: 'pointer',
                fontSize: '14px',
                fontWeight: 'bold'
              }}
            >
              ← Scroll Left
            </button>
            <span style={{ fontSize: '12px', color: '#666' }}>
              {history.length} items
            </span>
            <button 
              onClick={() => handleScroll('right')}
              style={{
                padding: '8px 12px',
                backgroundColor: '#5d35c4',
                color: '#fff',
                border: 'none',
                borderRadius: '4px',
                cursor: 'pointer',
                fontSize: '14px',
                fontWeight: 'bold'
              }}
            >
              Scroll Right →
            </button>
          </div>
          <div style={{ overflowX: 'auto' }} ref={tableContainerRef}>
            <table style={{ width: '100%', borderCollapse: 'collapse' }}>
              <thead>
                <tr style={{ borderBottom: '2px solid #ddd', backgroundColor: '#f5f5f5' }}>
                  <th style={{ padding: '12px', textAlign: 'left' }}>Type</th>
                  <th style={{ padding: '12px', textAlign: 'left' }}>Output File</th>
                  <th style={{ padding: '12px', textAlign: 'left' }}>Details</th>
                  <th style={{ padding: '12px', textAlign: 'left' }}>Timestamp</th>
                </tr>
              </thead>
              <tbody>
                {history.map((item, index) => (
                  <tr key={index} style={{ borderBottom: '1px solid #eee' }}>
                    <td style={{ padding: '12px' }}>
                      <span style={{ textTransform: 'capitalize', fontWeight: '500' }}>
                        {item.type}
                      </span>
                    </td>
                    <td style={{ padding: '12px' }}>
                      {item.output ? (
                        <div style={{ display: 'flex', gap: '10px', alignItems: 'center' }}>
                          <span style={{ flex: 1 }}>{item.output}</span>
                          <a 
                            href={`${API_URL}/download/${item.output}`} 
                            download
                            style={{ 
                              padding: '6px 12px',
                              backgroundColor: '#4caf50',
                              color: '#fff',
                              textDecoration: 'none',
                              borderRadius: '4px',
                              fontSize: '12px',
                              fontWeight: 'bold',
                              cursor: 'pointer',
                              whiteSpace: 'nowrap'
                            }}
                          >
                            Download
                          </a>
                        </div>
                      ) : (
                        '-'
                      )}
                    </td>
                    <td style={{ padding: '12px' }}>
                      {item.frames ? `${item.frames} frames${item.processing_time ? ` - ${item.processing_time.toFixed(2)}s` : ''}` : '-'}
                    </td>
                    <td style={{ padding: '12px', fontSize: '14px', color: '#666' }}>
                      {new Date(item.timestamp).toLocaleString()}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
};

export default History;
